pub(crate) fn positionals(args: &[String]) -> Vec<String> {
    let mut out = Vec::new();
    let mut skip = false;
    for (i, a) in args.iter().enumerate() {
        if skip {
            skip = false;
            continue;
        }
        if a == "--db" || a == "--domain" || a == "--product" {
            skip = true;
            continue;
        }
        if a.starts_with("--") || i == 0 {
            continue;
        }
        out.push(a.clone());
    }
    out
}
